<script setup>
import {computed} from 'vue'
const props=defineProps({graph:Object})
const y=(s,x)=>s.kind==='quadratic'?s.a*x*x+s.b*x+(s.c||0):s.kind==='inverse'?(x===0?NaN:s.k/x):s.k*x+s.b
const plot=computed(()=>{const g=props.graph;if(!g||![g.x_min,g.x_max,g.y_min,g.y_max].every(Number.isFinite)||g.x_min>=g.x_max||g.y_min>=g.y_max)return null;const scale=Math.min(270/(g.x_max-g.x_min),170/(g.y_max-g.y_min)),px=x=>35+(x-g.x_min)*scale,py=v=>25+(g.y_max-v)*scale;return {px,py,w:(g.x_max-g.x_min)*scale,h:(g.y_max-g.y_min)*scale,lines:g.series.map(s=>{let path='',prev=false,lastX;for(let i=0;i<=400;i++){const x=g.x_min+(g.x_max-g.x_min)*i/400,v=y(s,x);if(!Number.isFinite(v)||v<g.y_min||v>g.y_max){prev=false;continue}if(s.kind==='inverse'&&lastX*x<=0)prev=false;path+=`${prev?'L':'M'}${px(x)},${py(v)} `;prev=true;lastX=x}return {path,points:(s.mark_x||[]).map(x=>({x,y:y(s,x)}))}})}})
const expression=s=>s.kind==='quadratic'?`y=${s.a}x²${s.b>=0?'+':''}${s.b}x${(s.c||0)>=0?'+':''}${s.c||0}`:s.kind==='inverse'?`y=${s.k}/x`:`y=${s.k}x${s.b>=0?'+':''}${s.b}`
</script>
<template><figure v-if="plot" class="function-plot"><h3>{{graph.title}}</h3><svg viewBox="0 0 340 225" role="img" :aria-label="graph.title"><line x1="35" :y1="plot.py(0)" :x2="35+plot.w" :y2="plot.py(0)" stroke="currentColor"/><line :x1="plot.px(0)" y1="25" :x2="plot.px(0)" :y2="25+plot.h" stroke="currentColor"/><text :x="35+plot.w+6" :y="plot.py(0)">x</text><text :x="plot.px(0)+5" y="20">y</text><text x="35" :y="40+plot.h">{{graph.x_min}}</text><text :x="25+plot.w" :y="40+plot.h">{{graph.x_max}}</text><text x="4" y="32">{{graph.y_max}}</text><text x="4" :y="25+plot.h">{{graph.y_min}}</text><g v-for="(line,i) in plot.lines" :key="i" :style="{color:['#164b9b','#d75454','#168979','#8059b0'][i]}"><path :d="line.path" fill="none" stroke="currentColor" stroke-width="2"/><circle v-for="(p,j) in line.points" :key="j" :cx="plot.px(p.x)" :cy="plot.py(p.y)" r="3" fill="currentColor"/></g></svg><p v-for="(s,i) in graph.series" :key="i">{{expression(s)}} <span v-for="x in s.mark_x||[]" :key="x"> · ({{x}}, {{Number(y(s,x).toPrecision(5))}})</span></p></figure><p v-else role="alert">请核对函数坐标范围。</p></template>
<style scoped>.function-plot{margin:0}.function-plot svg{display:block;width:100%;max-height:300px}.function-plot text{fill:currentColor;font-size:11px}.function-plot p{font-size:12px;margin:4px 0}</style>
